<template><div class="upload"><div class="title"><i v-if="required">*</i>{{label}}</div><van-uploader v-model="files" :max-count="maxCount" :accept="accept"><div class="trigger"><van-icon name="photograph"/></div></van-uploader><p v-if="hint">{{hint}}</p><p v-if="error" class="error">{{error}}</p></div></template>
<script setup>import{computed}from'vue';const props=defineProps({modelValue:{type:Array,default:()=>[]},label:{type:String,default:'本人照片上传'},required:Boolean,hint:String,error:String,maxCount:{type:Number,default:1},accept:{type:String,default:'image/*'}});const emit=defineEmits(['update:modelValue','change']);const files=computed({get:()=>props.modelValue,set:v=>{emit('update:modelValue',v);emit('change',v)}})</script>
<style scoped>.upload{width:311px;padding:10px 0;box-sizing:border-box}.title{min-height:24px;color:#4E5969;font:500 16px/24px "PingFang SC",sans-serif}.title i{margin-right:2px;color:#F53F3F;font-style:normal}.trigger{width:80px;height:80px;margin-top:8px;display:flex;align-items:center;justify-content:center;border-radius:4px;color:#86909C;background:#F2F3F5}.trigger .van-icon{font-size:24px}.upload p{margin:8px 0 0;color:#86909C;font:400 12px/18px "PingFang SC",sans-serif}.upload .error{color:#F53F3F}</style>
